import type { LayerRow } from '@nitro-forge/editor-controls/layers/layer-model';
import type { CanvasLayer } from './prism-canvas-model';
import { prismLayerLabel } from './prism-layer-label';
import type { CanvasShape } from './prism-canvas-model';

/**
 * Prism engine adapter for NYC-Tron's `LayerStack`.
 *
 * Prism stores layers bottom to top (engine index 0 is the bottom layer);
 * `LayerStack` lists them top to bottom (row index 0 is the topmost layer).
 * Every function here converts between the two, so no index arithmetic lives
 * in the editor. Each command is one engine operation and so one undo step.
 */

/** A Prism layer as the editor reads it from the engine's `describe` state. */
export type PrismLayer = CanvasLayer & { name: string; /** Engine blend mode name; absent reads as `normal`. */ blend?: string };

/**
 * One engine operation produced from a {@linkcode LayerStack} callback. The
 * editor runs it through its single command path and shows `label` once the
 * engine accepts it.
 */
export type PrismLayerCommand =
  | { op: 'moveLayer'; payload: { id: number; to_index: number }; label: string }
  | { op: 'setLayerOpacity'; payload: { id: number; opacity: number }; label: string }
  | { op: 'setLayerBlend'; payload: { id: number; blend: string }; label: string }
  | { op: 'setLayerVisible'; payload: { id: number; visible: boolean }; label: string }
  | { op: 'renameLayer'; payload: { id: number; name: string }; label: string }
  | { op: 'removeLayer'; payload: { id: number }; label: string };

/** Row id for an engine layer id. */
export const prismLayerRowId = (id: number): string => String(id);

/**
 * The engine layer behind a row id.
 * @throws RangeError when no layer in `layers` has that id, which means the
 * callback came from rows the document has since replaced.
 */
function layerForRow(layers: readonly PrismLayer[], rowId: string): { layer: PrismLayer; index: number } {
  const index = layers.findIndex(layer => prismLayerRowId(layer.id) === rowId);
  const layer = layers[index];
  if (!layer) throw new RangeError(`No Prism layer for row ${rowId}`);
  return { layer, index };
}

const channel = (value: number | undefined) => Math.min(255, Math.max(0, Math.round(Number.isFinite(value) ? value! : 0)));

/** A shape's engine RGBA fill (0-255 per channel) as a CSS colour, or
 * `undefined` when the engine sent no usable fill. */
export function prismFillColour(shape: CanvasShape | undefined): string | undefined {
  const fill = shape?.fill;
  if (!fill || fill.length < 3) return undefined;
  const [r, g, b, a = 255] = fill;
  return `rgba(${channel(r)}, ${channel(g)}, ${channel(b)}, ${+(channel(a) / 255).toFixed(3)})`;
}

/**
 * Rows for `LayerStack`, topmost layer first. A blank engine name reads as its
 * kind and id. The detail line names Prism's kind ("Rectangle", "Ellipse",
 * "Raster"), and a shape row shows its fill. A raster row has no thumbnail:
 * its pixels have no single colour, and a scaled preview is not built yet.
 */
export function prismLayerRows(layers: readonly PrismLayer[]): LayerRow[] {
  return layers.map(layer => {
    const fill = layer.content?.type === 'shape' ? prismFillColour(layer.content.shape) : undefined;
    return {
      id: prismLayerRowId(layer.id),
      name: layer.name.trim() ? layer.name : `${prismLayerLabel(layer)} ${layer.id}`,
      visible: layer.visible,
      opacity: Math.min(1, Math.max(0, Number.isFinite(layer.opacity) ? layer.opacity : 1)),
      kind: layer.content?.type === 'shape' ? 'vector' as const : 'raster' as const,
      kindLabel: prismLayerLabel(layer),
      ...(fill ? { thumbnail: { fill } } : {}),
    };
  }).reverse();
}

/** The engine layer id for a selected row id, or `undefined` when no row is selected. */
export function prismSelectedRowId(selectedId: number | null): string | undefined {
  return selectedId === null ? undefined : prismLayerRowId(selectedId);
}

/**
 * `moveLayer` for a row landing on `toIndex` (0 = top), or `undefined` when
 * the layer is already there.
 */
export function prismMoveCommand(layers: readonly PrismLayer[], rowId: string, toIndex: number): PrismLayerCommand | undefined {
  const { layer, index } = layerForRow(layers, rowId);
  if (!Number.isInteger(toIndex) || toIndex < 0 || toIndex >= layers.length) throw new RangeError(`Row index ${toIndex} is outside 0..${layers.length - 1}`);
  const engineIndex = layers.length - 1 - toIndex;
  return engineIndex === index ? undefined : { op: 'moveLayer', payload: { id: layer.id, to_index: engineIndex }, label: 'Layer reordered' };
}

/**
 * `setLayerOpacity` for one released opacity gesture, or `undefined` when the
 * value did not change. `LayerStack` reports each completed drag once.
 */
export function prismOpacityCommand(layers: readonly PrismLayer[], rowId: string, opacity: number): PrismLayerCommand | undefined {
  const { layer } = layerForRow(layers, rowId);
  if (!Number.isFinite(opacity) || opacity < 0 || opacity > 1) throw new RangeError(`Opacity ${opacity} is outside 0..1`);
  return opacity === layer.opacity ? undefined : { op: 'setLayerOpacity', payload: { id: layer.id, opacity }, label: 'Layer opacity changed' };
}

/** `setLayerVisible` that flips the row's visibility. */
export function prismVisibilityCommand(layers: readonly PrismLayer[], rowId: string): PrismLayerCommand {
  const { layer } = layerForRow(layers, rowId);
  return { op: 'setLayerVisible', payload: { id: layer.id, visible: !layer.visible }, label: layer.visible ? 'Layer hidden' : 'Layer shown' };
}

/** `renameLayer` with the trimmed name `LayerStack` submitted, or `undefined` when it is unchanged. */
export function prismRenameCommand(layers: readonly PrismLayer[], rowId: string, name: string): PrismLayerCommand | undefined {
  const { layer } = layerForRow(layers, rowId);
  const next = name.trim();
  if (!next) throw new RangeError('A layer name needs at least one character');
  return next === layer.name ? undefined : { op: 'renameLayer', payload: { id: layer.id, name: next }, label: 'Layer renamed' };
}

/** `removeLayer` for the row's remove control, its screen-reader action or Delete on the focused row. The engine's undo restores it. */
export function prismRemoveCommand(layers: readonly PrismLayer[], rowId: string): PrismLayerCommand {
  const { layer } = layerForRow(layers, rowId);
  return { op: 'removeLayer', payload: { id: layer.id }, label: 'Layer removed' };
}

import type { CanvasLayer } from './prism-canvas-model';

/** Every kind of Prism layer has one name, used by the layer rows, the
 * toolbar and new layer names. The engine's `rect` enum never
 * reaches the screen. */
export type PrismLayerKind = 'rectangle' | 'ellipse' | 'raster';

export const PRISM_LAYER_LABELS: Readonly<Record<PrismLayerKind, string>> = {
  rectangle: 'Rectangle',
  ellipse: 'Ellipse',
  raster: 'Raster',
};

/** The kind of a layer, or of an engine shape enum (`rect`, `ellipse`). */
export function prismLayerKind(layer: Pick<CanvasLayer, 'content'> | 'rect' | 'ellipse'): PrismLayerKind {
  if (layer === 'rect') return 'rectangle';
  if (layer === 'ellipse') return 'ellipse';
  if (layer.content?.type !== 'shape') return 'raster';
  return layer.content.shape?.kind === 'ellipse' ? 'ellipse' : 'rectangle';
}

/** The kind's display name: "Rectangle", "Ellipse" or "Raster". */
export const prismLayerLabel = (layer: Parameters<typeof prismLayerKind>[0]): string => PRISM_LAYER_LABELS[prismLayerKind(layer)];

/** Below this editor width, contextual Layers overlays rather than resizing the artboard. */
export const PRISM_DOCKED_LAYERS_MIN_WIDTH = 1100;
/** Compact panel width; alpha.3 LayerStack collapses row opacity when space is tight. */
export const PRISM_LAYERS_PANEL_WIDTH = 280;

/**
 * Everything in the Layers panel except the layer list, at 100 % text: the
 * title row, the blend mode menu, the Straight alpha line, the two-row
 * opacity scrubber and Raise/Lower. The list gets the rest of the panel, so
 * none of these go under its fold. verify-prism-blend.mjs measures the drawn
 * panel against this number in Chromium.
 */
export const PRISM_LAYERS_HEAD_HEIGHT = 320;
/** One full LayerStack row: the list never shrinks below it, even where the head does not fit. */
export const PRISM_LAYER_LIST_MIN_HEIGHT = 56;

/** Geometry belongs to the editor viewport, never the native app window contract. */
/** Measured chrome, in editor coordinates. Larger text (200 %) grows the
 * toolbar and the tool rail, so the artboard and panels start below and
 * beside what was really laid out instead of at fixed offsets. */
export type PrismChromeMeasure = Readonly<{ toolbarBottom?: number; railRight?: number }>;

/** Toolbar and rail as drawn at 100 % text: a 48 pt toolbar at 12 pt and a 52 pt rail at 12 pt. */
export const PRISM_TOOLBAR_TOP = 12;
export const PRISM_DEFAULT_TOOLBAR_BOTTOM = 60;
export const PRISM_DEFAULT_RAIL_RIGHT = 64;
/** Gap between a piece of chrome and what sits below or beside it. */
const CHROME_GAP = 8;

export function prismViewportLayout(width: number, height: number, ratio: number, layersOpen: boolean, hasFillAction: boolean, chrome: PrismChromeMeasure = {}) {
  const narrow = width < 700;
  const short = height < 400;
  const dockedLayers = width >= PRISM_DOCKED_LAYERS_MIN_WIDTH;
  const aspect = Number.isFinite(ratio) && ratio > 0 ? ratio : 1;
  const toolbarBottom = Math.max(PRISM_DEFAULT_TOOLBAR_BOTTOM, chrome.toolbarBottom ?? 0);
  const railRight = Math.max(PRISM_DEFAULT_RAIL_RIGHT, chrome.railRight ?? 0);
  // The compact row keeps its name and remove action reachable at this width.
  const panelWidth = Math.max(1, Math.min(PRISM_LAYERS_PANEL_WIDTH, width - 24));
  // Grown chrome pushes the panel, rail and artboard down by the same amount.
  const grown = toolbarBottom - PRISM_DEFAULT_TOOLBAR_BOTTOM;
  const railTop = toolbarBottom + (short ? CHROME_GAP : CHROME_GAP * 2);
  const panelTop = short ? 8 : narrow ? toolbarBottom + 16 : 12;
  // In short narrow windows the palette stays to the right of the tool capsule.
  // Its contents scroll horizontally when raster actions need more width.
  const paletteSpace = Math.max(1, width - (short && narrow ? 88 : 24));
  const fillWidth = Math.min(hasFillAction ? 384 : narrow ? 220 : 320, paletteSpace);
  const fillLeft = short && narrow ? width - fillWidth - 12 : (width - fillWidth) / 2;
  // The panel stops above the fill bar only where the bar reaches under it;
  // beside the bar it may run to the editor's bottom gutter.
  const fillClearsPanel = !short && fillLeft + fillWidth <= width - 12 - panelWidth;
  const panelMaxHeight = Math.max(1, height - panelTop - (short ? 8 : fillClearsPanel ? 12 : 108));
  const layerListMaxHeight = Math.max(PRISM_LAYER_LIST_MIN_HEIGHT, Math.min(245, panelMaxHeight - PRISM_LAYERS_HEAD_HEIGHT));
  const canvasLeft = railRight + (narrow ? 12 : 24);
  // On a phone the artboard is centred on the screen: the right margin
  // matches the rail side, so the margins balance instead of 76 against 20.
  const canvasRight = layersOpen && dockedLayers ? panelWidth + 32 : narrow ? canvasLeft : 20;
  const canvasTop = (short ? 68 : 80) + grown;
  const canvasBottom = short ? 76 : 100;
  const availableWidth = Math.max(1, width - canvasLeft - canvasRight);
  const availableHeight = Math.max(1, height - canvasTop - canvasBottom);
  const canvasWidth = Math.max(0, Math.min(900, availableWidth, availableHeight * aspect));
  const canvasHeight = canvasWidth / aspect;
  return { narrow, short, dockedLayers, panelWidth, panelTop, panelMaxHeight, layerListMaxHeight, railTop,
    canvasLeft, canvasRight, canvasTop, canvasBottom, canvasWidth, canvasHeight,
    availableWidth, availableHeight, fillWidth, fillLeft };
}

/** Original accessible equivalents for simple axis-aligned shape transforms.
 * These are command payloads, never a second geometry/document model. */
export const SHAPE_TRANSFORMS = [
  { id: 'left', title: 'Move left 1 px', dx: -1, dy: 0, scale_x: 1, scale_y: 1 },
  { id: 'right', title: 'Move right 1 px', dx: 1, dy: 0, scale_x: 1, scale_y: 1 },
  { id: 'up', title: 'Move up 1 px', dx: 0, dy: -1, scale_x: 1, scale_y: 1 },
  { id: 'down', title: 'Move down 1 px', dx: 0, dy: 1, scale_x: 1, scale_y: 1 },
  { id: 'left-fast', title: 'Move left 10 px', dx: -10, dy: 0, scale_x: 1, scale_y: 1 },
  { id: 'right-fast', title: 'Move right 10 px', dx: 10, dy: 0, scale_x: 1, scale_y: 1 },
  { id: 'up-fast', title: 'Move up 10 px', dx: 0, dy: -10, scale_x: 1, scale_y: 1 },
  { id: 'down-fast', title: 'Move down 10 px', dx: 0, dy: 10, scale_x: 1, scale_y: 1 },
  { id: 'grow', title: 'Enlarge 10% from top-left', dx: 0, dy: 0, scale_x: 1.1, scale_y: 1.1 },
  { id: 'shrink', title: 'Shrink 10% from top-left', dx: 0, dy: 0, scale_x: .9, scale_y: .9 },
] as const;

export function shapeTransformPayload(id: number, action: string) {
  if (!Number.isSafeInteger(id) || id <= 0) return null;
  const transform = SHAPE_TRANSFORMS.find(item => item.id === action);
  if (!transform) return null;
  const { dx, dy, scale_x, scale_y } = transform;
  return { id, dx, dy, scale_x, scale_y };
}

import { layerOpacityFromPercent, validateLayerBlend, type LayerAlphaOption, type LayerBlendMode, type LayerBlendSpace, type LayerBlendValue } from '@nitro-forge/editor-controls/layers/layer-blend-model';
import type { CommandMenuItem } from '@/components/nyc-tron/ui/components/shell/MenuButton';
import type { PrismLayer, PrismLayerCommand } from './prism-layers';

export type { PrismLayer, PrismLayerCommand } from './prism-layers';

/*
 * Prism adapter for the NYC-Tron v1.0.0-rc.2 B-11 layer blend model, shared by
 * every host that renders the Prism editor. Decision D7: the Layers panel
 * shows the blend mode in Tron's MenuButton and the Straight alpha line as
 * text, both from these catalogs, and keeps Forge's configured
 * PrecisionScrubber for opacity. `layer-blend-model` has no imports and
 * MenuButton is imported for its item type only, so this module and its node
 * test run without React Native.
 */

/**
 * The 13 modes Prism `setLayerBlend` accepts, in its menu order. This package
 * talks to Prism through op names only, so the list is repeated here;
 * apps/studio-preview/tests/prism-blend.e2e.test.ts checks it against
 * `BLEND_MODES` in packages/prism.
 */
export const PRISM_BLEND_MODE_IDS = [
  'normal', 'multiply', 'screen', 'overlay', 'darken', 'lighten',
  'color-dodge', 'color-burn', 'hard-light', 'soft-light',
  'difference', 'exclusion', 'add',
] as const;
export type PrismBlendModeId = (typeof PRISM_BLEND_MODE_IDS)[number];

const titles: Record<PrismBlendModeId, string> = {
  normal: 'Normal', multiply: 'Multiply', screen: 'Screen', overlay: 'Overlay', darken: 'Darken', lighten: 'Lighten',
  'color-dodge': 'Color dodge', 'color-burn': 'Color burn', 'hard-light': 'Hard light', 'soft-light': 'Soft light',
  difference: 'Difference', exclusion: 'Exclusion', add: 'Add',
};

export const PRISM_BLEND_MODES: readonly LayerBlendMode[] = PRISM_BLEND_MODE_IDS.map(id => ({ id, label: titles[id] }));

/**
 * Prism blends 8-bit RGBA as stored, with no linearisation and no ICC
 * handling, so the one space is encoded and named for the engine's channels.
 * There is no op to change it.
 */
export const PRISM_BLEND_SPACES = [
  { id: 'prism-rgba8', label: 'Prism RGBA', transfer: 'encoded', modeIds: PRISM_BLEND_MODE_IDS },
] as const satisfies readonly LayerBlendSpace[];

/**
 * Prism stores and composites straight alpha and has no op that changes a
 * layer's alpha representation, so Premultiplied is not offered. With one
 * entry the Layers panel shows it as text, not a menu.
 */
export const PRISM_ALPHA_MODES = [
  { id: 'straight', label: 'Straight alpha' },
] as const satisfies readonly LayerAlphaOption[];

/**
 * The Layers panel opacity scrubber, as before B-11: whole percent steps, so
 * each "−"/"+" press, arrow key or screen-reader increment moves 1 %.
 */
export const PRISM_OPACITY_SCRUBBER = {
  label: 'Layer opacity', min: 0, max: 100, step: 1, unit: '%', detents: [0, 25, 50, 75, 100],
} as const satisfies { label: string; min: number; max: number; step: number; unit: string; detents: readonly number[] };

export const isPrismBlendMode = (mode: unknown): mode is PrismBlendModeId =>
  typeof mode === 'string' && (PRISM_BLEND_MODE_IDS as readonly string[]).includes(mode);

const blendValue = (mode: PrismBlendModeId, opacity: number): LayerBlendValue => {
  const value: LayerBlendValue = { mode, opacity, spaceId: PRISM_BLEND_SPACES[0].id, alphaMode: PRISM_ALPHA_MODES[0].id };
  validateLayerBlend(value, PRISM_BLEND_MODES, PRISM_BLEND_SPACES, PRISM_ALPHA_MODES);
  return value;
};

/**
 * The layer's blend value in Tron's model, checked by Tron's
 * `validateLayerBlend` against the Prism catalogs. A layer without `blend`
 * reads as `normal`, the engine default. A blend name Prism does not list
 * returns `undefined`, so the host can say so.
 * @throws {RangeError} The layer's opacity is outside 0..1.
 */
export function prismLayerBlendValue(layer: PrismLayer): LayerBlendValue | undefined {
  const mode = layer.blend ?? 'normal';
  return isPrismBlendMode(mode) ? blendValue(mode, layer.opacity) : undefined;
}

/**
 * Items for the blend mode MenuButton, built as Tron's LayerBlendAndOpacity
 * builds its own: a mode is disabled when it has an unavailable reason or the
 * compositing space does not list it.
 */
export function prismBlendMenuItems(): CommandMenuItem[] {
  const space = PRISM_BLEND_SPACES[0];
  return PRISM_BLEND_MODES.map(mode => ({
    id: mode.id,
    label: mode.label,
    ...(mode.unavailableReason ? { description: mode.unavailableReason } : {}),
    disabled: !!mode.unavailableReason || !(space.modeIds as readonly string[]).includes(mode.id),
  }));
}

/** One Layers panel commit: a blend mode menu choice or a released opacity percent. */
export type PrismBlendChange =
  | { readonly kind: 'mode'; readonly mode: string }
  | { readonly kind: 'opacity'; readonly percent: number };

/**
 * A Layers panel commit as one Prism command, or `undefined` when the value
 * did not change. Validation runs here, before any engine call: each command
 * is one `setLayerBlend` or one `setLayerOpacity`, so one undo step. A mode
 * goes through Tron's `validateLayerBlend`; a percent through Tron's
 * `layerOpacityFromPercent`.
 * @throws {RangeError} An unknown mode, a percent outside 0..100, or a layer
 * id that is no longer in `layers`.
 */
export function prismBlendCommand(
  layers: readonly PrismLayer[],
  layerId: number,
  change: PrismBlendChange,
): PrismLayerCommand | undefined {
  const layer = layers.find(item => item.id === layerId);
  if (!layer) throw new RangeError(`No Prism layer ${layerId}`);
  if (change.kind === 'mode') {
    const { mode } = change;
    if (!isPrismBlendMode(mode)) throw new RangeError(`Prism has no "${mode}" blend mode.`);
    blendValue(mode, layer.opacity);
    return mode === (layer.blend ?? 'normal') ? undefined : { op: 'setLayerBlend', payload: { id: layer.id, blend: mode }, label: 'Layer blend mode changed' };
  }
  const opacity = layerOpacityFromPercent(change.percent);
  return opacity === layer.opacity ? undefined : { op: 'setLayerOpacity', payload: { id: layer.id, opacity }, label: 'Layer opacity changed' };
}

/** Bounded portable PNG encoding for the engine's straight-alpha RGBA preview. */
export const MAX_PREVIEW_PIXELS = 1_048_576;
export function validatePreviewSize(width: number, height: number): void {
  if (!Number.isInteger(width) || !Number.isInteger(height) || width <= 0 || height <= 0
    || width > 4096 || height > 4096 || width * height > MAX_PREVIEW_PIXELS) {
    throw new Error('Canvas preview supports up to 1,048,576 pixels and 4096 pixels per side. Your document is unchanged.');
  }
}
const crcTable = Uint32Array.from({ length: 256 }, (_, index) => {
  let value = index;
  for (let bit = 0; bit < 8; bit++) value = (value & 1) ? 0xedb88320 ^ (value >>> 1) : value >>> 1;
  return value >>> 0;
});
function crc32(bytes: Uint8Array): number {
  let crc = 0xffffffff;
  for (const byte of bytes) crc = crcTable[(crc ^ byte) & 255]! ^ (crc >>> 8);
  return (crc ^ 0xffffffff) >>> 0;
}
function chunk(type: string, data: Uint8Array): Uint8Array {
  const out = new Uint8Array(data.length + 12);
  const view = new DataView(out.buffer);
  view.setUint32(0, data.length);
  out.set(Array.from(type, char => char.charCodeAt(0)), 4);
  out.set(data, 8);
  view.setUint32(out.length - 4, crc32(out.subarray(4, out.length - 4)));
  return out;
}
/** Encode an 8-bit RGBA image without native resources or platform-specific APIs. */
export function encodeRgbaPng(width: number, height: number, rgba: Uint8Array): Uint8Array {
  validatePreviewSize(width, height);
  if (rgba.length !== width * height * 4) throw new Error('The engine returned an invalid RGBA preview length.');
  const stride = width * 4;
  const scanlines = new Uint8Array((stride + 1) * height);
  for (let y = 0; y < height; y++) scanlines.set(rgba.subarray(y * stride, (y + 1) * stride), y * (stride + 1) + 1);
  // RFC1950 zlib wrapping RFC1951 stored blocks. No compression dependency is
  // needed; bounded preview data trades a little size for native/web parity.
  const zlib = new Uint8Array(2 + scanlines.length + Math.ceil(scanlines.length / 65535) * 5 + 4);
  zlib.set([0x78, 0x01]);
  let offset = 2;
  for (let start = 0; start < scanlines.length; start += 65535) {
    const size = Math.min(65535, scanlines.length - start);
    zlib[offset++] = start + size === scanlines.length ? 1 : 0;
    zlib[offset++] = size & 255; zlib[offset++] = size >>> 8;
    zlib[offset++] = (~size) & 255; zlib[offset++] = ((~size) >>> 8) & 255;
    zlib.set(scanlines.subarray(start, start + size), offset);
    offset += size;
  }
  let a = 1, b = 0;
  for (const byte of scanlines) { a = (a + byte) % 65521; b = (b + a) % 65521; }
  new DataView(zlib.buffer).setUint32(offset, ((b << 16) | a) >>> 0);
  const header = new Uint8Array(13);
  const headerView = new DataView(header.buffer);
  headerView.setUint32(0, width); headerView.setUint32(4, height);
  header.set([8, 6, 0, 0, 0], 8);
  const chunks = [new Uint8Array([137, 80, 78, 71, 13, 10, 26, 10]), chunk('IHDR', header), chunk('IDAT', zlib), chunk('IEND', new Uint8Array())];
  const png = new Uint8Array(chunks.reduce((sum, data) => sum + data.length, 0));
  offset = 0;
  for (const data of chunks) { png.set(data, offset); offset += data.length; }
  return png;
}
